    let mut ranks: Vec<u8> = Vec::new();
    let mut suits: Vec<char> = Vec::new();
    for token in hand.split_whitespace() {
        let suit = token.chars().last().unwrap();
        let rank_str = &token[..token.len() - 1];
        ranks.push(rank_value(rank_str));
        suits.push(suit);
    }

